package com.svb.common.valueobjects;

/**
 * @author Neelima
 *
**/

public class ReplenishmentHistoryVO {

	private String replenishDate;
	private String productName;
	private String replenishmentReq;
	private String productId;
	private String productTypeId;
	private String productImageFile;
	private String productReplmId;
	private String purchaseDate;
	private String productResource;
	private String productMainId;

	public String getReplenishDate() {
		return replenishDate;
	}

	public void setReplenishDate(String replenishDate) {
		this.replenishDate = replenishDate;
	}

	public String getProductName() {
		return productName;
	}

	public void setProductName(String productName) {
		this.productName = productName;
	}

	public String getReplenishmentReq() {
		return replenishmentReq;
	}

	public void setReplenishmentReq(String replenishmentReq) {
		this.replenishmentReq = replenishmentReq;
	}

	public String getProductId() {
		return productId;
	}

	public void setProductId(String productId) {
		this.productId = productId;
	}

	public String getProductTypeId() {
		return productTypeId;
	}

	public void setProductTypeId(String productTypeId) {
		this.productTypeId = productTypeId;
	}

	public String getProductImageFile() {
		return productImageFile;
	}

	public void setProductImageFile(String productImageFile) {
		this.productImageFile = productImageFile;
	}

	public String getProductReplmId() {
		return productReplmId;
	}

	public void setProductReplmId(String productReplmId) {
		this.productReplmId = productReplmId;
	}

	public String getPurchaseDate() {
		return purchaseDate;
	}

	public void setPurchaseDate(String purchaseDate) {
		this.purchaseDate = purchaseDate;
	}

	public String getProductResource() {
		return productResource;
	}

	public void setProductResource(String productResource) {
		this.productResource = productResource;
	}

	public String getProductMainId() {
		return productMainId;
	}

	public void setProductMainId(String productMainId) {
		this.productMainId = productMainId;
	}

}
